  ('vocab-import-29cf0a63a0aa34033b7fa5c5', 'newspaper', 'ˈnuzˌpeɪpər', 'Báo, báo chí.', 'a daily or weekly publication on folded sheets; contains news and articles and advertisements', 'noun', 'he read his newspaper at breakfast', 'Nghĩa trong ngữ cảnh: Báo, báo chí.', 'Media and communication', 'B1', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
  ('vocab-import-039f7bd6bc6c6e65355879d9', 'paint', 'peɪnt', 'Sơn.', 'a substance used as a coating to protect or decorate a surface (especially a mixture of pigment suspended in a liquid); dries to form a hard coating', 'noun', 'artists use `paint'' and `pigment'' interchangeably', 'Nghĩa trong ngữ cảnh: Sơn.', 'Tools and devices', 'B1', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
