  ('vocab-import-749440ec6a5039dc8c9a683c', 'helmet', 'ˈhɛlmət', 'Mũ sắt (bộ đội, lính cứu hoả... ).', 'armor plate that protects the head', 'noun', 'The medieval knight wore a steel helmet to protect his head in battle.', 'Nghĩa trong ngữ cảnh: Mũ sắt (bộ đội, lính cứu hoả... ).', 'Tools and devices', 'C1', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
  ('vocab-import-3d1058f7a20cf635b52b7c5d', 'ideology', 'ˌaɪdiˈɑləʤi', 'Ý thức hệ, tư tưởng, hệ tư tưởng (của một giai cấp... ), lý tưởng.', 'an orientation that characterizes the thinking of a group or nation', 'noun', 'The company''s ideology emphasizes sustainability and social responsibility above profits.', 'Nghĩa trong ngữ cảnh: Ý thức hệ, tư tưởng, hệ tư tưởng (của một giai cấp... ), lý tưởng.', 'Society and politics', 'C1', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
  ('vocab-import-efb36fd18666d99c199d09d2', 'inclusion', 'ˌɪnˈkluʒən', 'Sự gồm cả, sự kể vào, sự kể cả.', 'the state of being included', 'noun', 'The inclusion of everyone''s feedback made the project much stronger.', 'Nghĩa trong ngữ cảnh: Sự gồm cả, sự kể vào, sự kể cả.', 'Society and politics', 'C1', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
  ('vocab-import-da216147114e35d6e5acc5d4', 'inning', 'ˈɪnɪŋ', 'Lượt chơi của một phía; lượt chơi của một cầu thủ (crickê, bóng chày).', '(baseball) one of nine divisions of play during which each team has a turn at bat', 'noun', 'The home team scored three runs in the fifth inning of yesterday''s game.', 'Nghĩa trong ngữ cảnh: Lượt chơi của một phía; lượt chơi của một cầu thủ (crickê, bóng chày).', 'Sports and games', 'C1', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
  ('vocab-import-1a4e4a7cc4e8f5280a685bcc', 'insect', 'ˈɪnˌsɛkt', 'Sâu bọ, côn trùng.', 'small air-breathing arthropod', 'noun', 'A tiny insect landed on my arm during the picnic yesterday.', 'Nghĩa trong ngữ cảnh: Sâu bọ, côn trùng.', 'Science', 'C1', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
