  ('vocab-import-61e652ad7c7bbd98dd4dca2b', 'liar', 'laɪər', 'Kẻ nói dối, kẻ nói láo, kẻ nói điêu; kẻ hay nói dối, kẻ hay nói điêu.', 'a person who has lied or who lies repeatedly', 'noun', 'Everyone knew he was a liar after he got caught making up stories.', 'Nghĩa trong ngữ cảnh: Kẻ nói dối, kẻ nói láo, kẻ nói điêu; kẻ hay nói dối, kẻ hay nói điêu.', 'Qualities and descriptions', 'C1', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
  ('vocab-import-47e69de3e47edf25288a932c', 'machinery', 'məˈʃinəri', 'Máy móc,cơ giới', 'machines or machine systems collectively', 'noun', 'The factory''s old machinery needs to be replaced with modern equipment.', 'Nghĩa trong ngữ cảnh: Máy móc,cơ giới', 'Technology', 'C1', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
