  ('vocab-import-c4bb896961f2dfd5f739d877', 'halt', 'hɔlt', 'Sự tạm nghỉ, sự tạm dừng lại (trong lúc đang đi... ).', 'the state of inactivity following an interruption', 'noun', 'the negotiations were in arrest', 'Nghĩa trong ngữ cảnh: Sự tạm nghỉ, sự tạm dừng lại (trong lúc đang đi... ).', 'Actions and movement', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
  ('vocab-import-4ff615253469989932532e92', 'han', 'hɑn', 'Nhà Hán (206 trước Công Nguyên - 220 Công Nguyên) trong lịch sử Trung Hoa.', 'imperial dynasty that ruled China (most of the time from 206 BC to AD 220) and expanded its boundaries and developed its bureaucracy; remembered as one of the great eras of Chinese civilization', 'noun', 'The Han dynasty was one of China''s greatest and most influential periods.', 'Nghĩa trong ngữ cảnh: Nhà Hán (206 trước Công Nguyên - 220 Công Nguyên) trong lịch sử Trung Hoa.', 'Events', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
  ('vocab-import-c6e642e2b148af42898b6913', 'imaging', 'ˈɪmɪʤɪŋ', 'Dạng phân từ hiện tại và danh động từ (gerund) của image.', 'the ability to form mental images of things or events', 'noun', 'he could still hear her in his imagination', 'Nghĩa trong ngữ cảnh: Dạng phân từ hiện tại và danh động từ (gerund) của image.', 'Health and medicine', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
  ('vocab-import-ecfaa9a2a27ee074f9ee8ff7', 'inability', 'ˌɪnəˈbɪlɪti', 'Sự không có khả năng, sự bất lực, sự bất tài.', 'lack of ability (especially mental ability) to do something', 'noun', 'His inability to understand math made high school algebra really difficult.', 'Nghĩa trong ngữ cảnh: Sự không có khả năng, sự bất lực, sự bất tài.', 'Qualities and descriptions', 'C2', ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], ARRAY[]::text[], NULL),
